-- Consolidate the maze walkthrough from 18 steps to 13.
-- Remaps slug 25 progress by instructional milestone.
-- Updates the learning objective that still described the old power sentence.
-- Does not change the BOM, wiring, firmware, is_published, or projects 8, 18, 23, or 24.

do $$
begin
  if not exists (
    select 1 from public.projects
    where slug = '25' and title = 'Arduino LED Matrix Maze Game' and is_published = false
  ) then
    raise exception 'slug 25 is not the unpublished LED matrix maze';
  end if;
end;
$$;

update public.user_projects as progress
set current_step = case
  when progress.current_step <= 1 then 0
  when progress.current_step = 2 then 1
  when progress.current_step <= 4 then 2
  when progress.current_step <= 6 then 3
  when progress.current_step <= 8 then 4
  when progress.current_step = 9 then 5
  when progress.current_step = 10 then 6
  when progress.current_step <= 12 then 7
  when progress.current_step = 13 then 8
  when progress.current_step = 14 then 9
  when progress.current_step = 15 then 10
  when progress.current_step = 16 then 11
  else 12
end
from public.projects as project
where progress.project_id = project.id
  and project.slug = '25';

update public.projects
set learning_objectives = array[
    'Wire an FC-16 MAX7219 matrix and a five-pin joystick to an Arduino Uno',
    'Share 5 V and ground on a breadboard while both modules stay beside it',
    'Move one dot through five fixed mazes with a deadzone and a debounced button',
    'Read a level time from millis() in the Serial Monitor'
]
where slug = '25'
  and is_published = false;

delete from public.project_steps
where project_id = (select id from public.projects where slug = '25');

insert into public.project_steps (
  project_id, sort_order, stage_sort_order, stage_title, title, description, tip, blocks
)
select project.id, step.sort_order, step.stage_sort_order, step.stage_title, step.title, step.description, step.tip, step.blocks
from public.projects as project
cross join (
  values
  (0, 0, $maze13$Understand the project$maze13$, $maze13$What You're Building$maze13$, $maze13$A joystick moves one blinking dot through five mazes on an 8×8 LED matrix.$maze13$, null, $maze13$[{"type":"components","heading":"Parts","items":[{"id":"arduino-uno-r3","name":"Arduino Uno R3","illustrationId":"arduino-uno","owned":false,"quantity":1},{"id":"max7219","name":"MAX7219 8×8 LED matrix","illustrationId":"led-matrix","owned":false,"quantity":1},{"id":"joystick","name":"Analog joystick module","illustrationId":"joystick","owned":false,"quantity":1},{"id":"breadboard","name":"Breadboard","illustrationId":"breadboard","owned":false,"quantity":1},{"id":"jumper-wires","name":"Male-to-male jumper wires","illustrationId":"jumper-wires","owned":false,"quantity":2},{"id":"jumper-male-female","name":"Male-to-female jumper wires","illustrationId":"jumper-wires","owned":false,"quantity":10},{"id":"usb-data-cable","name":"USB data cable","illustrationId":"usb-cable","owned":false,"quantity":1},{"id":"usb-power-source","name":"USB power source","illustrationId":"generic-module","owned":false,"quantity":1}]},{"type":"text","heading":"The game","body":"You guide one LED through five mazes that are written into the sketch, so each level is the same maze every time. Walls stay lit. The player blinks quickly, on for 120 ms and off for 120 ms. The goal winks slowly: on for most of each 800 ms, then off. If the player stands on the goal, the fast blink wins, so the goal does not show through the player. Empty squares stay off. Push the stick to move one square. A wall or the edge of the grid blocks the move. Reaching the goal loads the next maze. The joystick button restarts the level you are on. After level 5, one LED runs around the border and the button starts again at level 1. The Serial Monitor at 9600 baud prints each level time in milliseconds, and the total when level 5 is finished. You will place the Uno and the breadboard, connect both modules beside the board, and upload one sketch."},{"type":"expected","heading":"What done looks like","body":"All five mazes can be finished with the stick, and the Serial Monitor shows each level time and the total."}]$maze13$::jsonb),
  (1, 0, $maze13$Understand the project$maze13$, $maze13$Identify the LED Matrix and Joystick$maze13$, $maze13$Both modules are already assembled. Match the silk labels, and do not solder a header.$maze13$, null, $maze13$[{"type":"text","heading":"FC-16 matrix","body":"Use an assembled FC-16 MAX7219 module with the 8×8 matrix seated and a 5-pin male input header already soldered on. Some listings are a kit with a loose header. If the header is not soldered, stop. This guide does not include soldering. A bare MAX7219 chip, or a board with a different header, is not this part. Lay the board flat, LED face up, with the input header on the right. From the top that header is CLK, CS, DIN, GND, and VCC. With the header on the right, row 0 is the top of the grid and column 0 is the left. The library call setPoint(row, column) uses that order. PCB text may look upside down. That is the FC-16 mounting MD_MAX72XX expects. The header is not inserted into the breadboard. The module runs from 5 V. Do not power it from the Uno 3.3 V pin. Each pin takes the female socket of a male-to-female jumper, and the male pin goes to the Uno or to a breadboard rail. Leave the sketch intensity at 2."},{"type":"text","heading":"KY-023 joystick","body":"Use a preassembled two-axis module with five male pins, sold as KY-023 or a PS2-style stick. It also runs from 5 V. The usual silk order is GND, +5V, VRx, VRy, and SW. If your silk prints a different order, follow the silk. VRx and VRy rest near the middle of the 0 to 1023 analog range. SW connects to GND when pressed. The sketch uses INPUT_PULLUP, so an unpressed button reads HIGH. Each pin takes a female socket. The male end goes to the Uno or to a rail. Do not plug this header into the breadboard."},{"type":"warning","body":"Do not turn the matrix intensity up to 15, and do not light all 64 LEDs at full brightness from a weak USB port. This game keeps intensity at 2."}]$maze13$::jsonb),
  (2, 1, $maze13$Build the circuit$maze13$, $maze13$Set Up the Arduino and Power Rails$maze13$, $maze13$The Uno and the breadboard share 5 V and ground. Both modules stay beside the breadboard.$maze13$, $maze13$Both rail jumpers are male-to-male.$maze13$, $maze13$[{"type":"text","heading":"Placement and rails","body":"Put the Uno on the left with the USB socket toward you and the digital header facing the breadboard. Put the breadboard on the right. Leave USB unplugged. Leave both modules off the breadboard. Do not twist two jumpers into one header pin. The Uno has one 5 V pin, and both modules need 5 V and ground, so the left breadboard rails distribute that supply. Use two male-to-male jumpers. One end of each sits in the Uno female header. The other end sits in the rail. Connect Uno 5 V to the left red rail, row 1. Connect the Uno GND pin beside it to the left blue rail, row 1. The red rail is Uno 5 V. The blue rail is Uno ground. They are separate. Do not connect them to each other, and do not use the Uno 3.3 V pin."},{"type":"wiring","heading":"Uno power rails","nodes":[{"id":"arduino","name":"Arduino Uno","illustrationId":"arduino-uno"}],"connections":[],"assembly":{"parts":[],"jumpers":["uno-5v","uno-gnd"]}},{"type":"expected","heading":"Check","body":"The Uno and breadboard are side by side, USB is unplugged, neither module header is in the breadboard, 5 V is on the red rail, and GND is on the blue rail."}]$maze13$::jsonb),
  (3, 1, $maze13$Build the circuit$maze13$, $maze13$Connect the LED Matrix$maze13$, $maze13$The FC-16 stays off the breadboard. Five male-to-female jumpers connect its header.$maze13$, $maze13$If the silk names the pins in another order, follow the silk. The female socket still goes on the module pin.$maze13$, $maze13$[{"type":"text","heading":"Five wires","body":"Lay the FC-16 flat beyond the far end of the breadboard, LED face up, with a clear gap so the board does not touch the breadboard. Keep the input header on the right. From the top that header is CLK, CS, DIN, GND, and VCC. Do not plug the five-pin header into the breadboard. Each wire is male-to-female. The female socket goes on the module pin, and the male pin goes to the rail or the Uno. A 20 cm jumper is long enough for this span. Connect VCC to the left red rail and GND to the left blue rail. Connect CLK to D13, CS to D10, and DIN to D11. D13 is the clock, D10 is chip select, also labelled LOAD or CS on some boards, and D11 is the data pin the library calls DIN. The signal wires do not enter the breadboard."},{"type":"wiring","heading":"Matrix","nodes":[{"id":"arduino","name":"Arduino Uno","illustrationId":"arduino-uno"},{"id":"matrix","name":"LED Matrix","illustrationId":"led-matrix"}],"connections":[{"fromComponent":"Arduino Uno","fromPin":"5V","toComponent":"LED Matrix","toPin":"VCC","signal":"power"},{"fromComponent":"Arduino Uno","fromPin":"GND","toComponent":"LED Matrix","toPin":"GND","signal":"ground"},{"fromComponent":"Arduino Uno","fromPin":"D13","toComponent":"LED Matrix","toPin":"CLK","signal":"signal"},{"fromComponent":"Arduino Uno","fromPin":"D10","toComponent":"LED Matrix","toPin":"CS","signal":"signal"},{"fromComponent":"Arduino Uno","fromPin":"D11","toComponent":"LED Matrix","toPin":"DIN","signal":"signal"}],"assembly":{"parts":["matrix"],"jumpers":["matrix-gnd","matrix-vcc","matrix-clk","matrix-cs","matrix-din"]}},{"type":"expected","heading":"Check","body":"Five male-to-female jumpers are fitted, the header is still off the breadboard, and the diagram matches the board in front of you."}]$maze13$::jsonb),
  (4, 1, $maze13$Build the circuit$maze13$, $maze13$Connect the Joystick$maze13$, $maze13$The joystick stays beside the breadboard, where your hand does not cover the display.$maze13$, $maze13$If the silk order differs, follow the silk and move these five sockets with it.$maze13$, $maze13$[{"type":"text","heading":"Five wires","body":"Lay the joystick flat beyond the near end of the breadboard, on the same side as the USB socket, with a clear gap so it does not touch the breadboard or the matrix. Your hand then stays off the display. Do not plug the header into the breadboard. The usual header order is GND, +5V, VRx, VRy, and SW. Fit a female socket on each pin. Connect GND to the left blue rail and +5V to the left red rail, so the stick shares the Uno 5 V and ground with the matrix. Connect VRx to A0, VRy to A1, and SW to D2. Those three wires do not enter the breadboard. Leave the stick centred while you fit the sockets so you do not bend the header."},{"type":"wiring","heading":"Joystick","nodes":[{"id":"arduino","name":"Arduino Uno","illustrationId":"arduino-uno"},{"id":"joystick","name":"Joystick","illustrationId":"joystick"}],"connections":[{"fromComponent":"Arduino Uno","fromPin":"5V","toComponent":"Joystick","toPin":"+5V","signal":"power"},{"fromComponent":"Arduino Uno","fromPin":"GND","toComponent":"Joystick","toPin":"GND","signal":"ground"},{"fromComponent":"Arduino Uno","fromPin":"A0","toComponent":"Joystick","toPin":"VRx","signal":"signal"},{"fromComponent":"Arduino Uno","fromPin":"A1","toComponent":"Joystick","toPin":"VRy","signal":"signal"},{"fromComponent":"Arduino Uno","fromPin":"D2","toComponent":"Joystick","toPin":"SW","signal":"signal"}],"assembly":{"parts":["joystick"],"jumpers":["joy-gnd","joy-5v","joy-x","joy-y","joy-sw"]}},{"type":"expected","heading":"Check","body":"The stick is clear of the matrix, five female sockets are on its header, and the diagram matches those pins."}]$maze13$::jsonb),
  (5, 1, $maze13$Build the circuit$maze13$, $maze13$Check the Complete Circuit$maze13$, $maze13$Count 2 male-to-male jumpers and 10 male-to-female jumpers before you plug in USB.$maze13$, null, $maze13$[{"type":"wiring","heading":"Complete circuit","nodes":[{"id":"arduino","name":"Arduino Uno","illustrationId":"arduino-uno"},{"id":"matrix","name":"LED Matrix","illustrationId":"led-matrix"},{"id":"joystick","name":"Joystick","illustrationId":"joystick"}],"connections":[{"fromComponent":"Arduino Uno","fromPin":"5V","toComponent":"LED Matrix","toPin":"VCC","signal":"power"},{"fromComponent":"Arduino Uno","fromPin":"GND","toComponent":"LED Matrix","toPin":"GND","signal":"ground"},{"fromComponent":"Arduino Uno","fromPin":"5V","toComponent":"Joystick","toPin":"+5V","signal":"power"},{"fromComponent":"Arduino Uno","fromPin":"GND","toComponent":"Joystick","toPin":"GND","signal":"ground"},{"fromComponent":"Arduino Uno","fromPin":"D13","toComponent":"LED Matrix","toPin":"CLK","signal":"signal"},{"fromComponent":"Arduino Uno","fromPin":"D10","toComponent":"LED Matrix","toPin":"CS","signal":"signal"},{"fromComponent":"Arduino Uno","fromPin":"D11","toComponent":"LED Matrix","toPin":"DIN","signal":"signal"},{"fromComponent":"Arduino Uno","fromPin":"A0","toComponent":"Joystick","toPin":"VRx","signal":"signal"},{"fromComponent":"Arduino Uno","fromPin":"A1","toComponent":"Joystick","toPin":"VRy","signal":"signal"},{"fromComponent":"Arduino Uno","fromPin":"D2","toComponent":"Joystick","toPin":"SW","signal":"signal"}]},{"type":"test","heading":"What to verify","body":"Count 2 male-to-male jumpers and 10 male-to-female jumpers. The female socket is on the module, and the male pin is in the Uno or in a rail. Uno 5 V feeds the red rail, and Uno GND feeds the blue rail. The red and blue rails are not joined. No jumper is in the Uno 3.3 V pin. Matrix CLK, CS, and DIN are D13, D10, and D11. Joystick VRx, VRy, and SW are A0, A1, and D2. Both headers are off the breadboard, and the matrix header reads CLK, CS, DIN, GND, VCC from the top. USB is still unplugged. Open Connections on the diagram to read each pair."}]$maze13$::jsonb),
  (6, 2, $maze13$Prepare the software$maze13$, $maze13$Set Up Arduino IDE$maze13$, $maze13$The sketch targets an Arduino Uno and MD_MAX72XX 3.5.1.$maze13$, null, $maze13$[{"type":"text","heading":"Board and port","body":"Install the Arduino IDE from arduino.cc. Open Tools, Board, Arduino AVR Boards, and choose Arduino Uno. Plug the USB data cable into the Uno and the computer. Open Tools, Port, and select the port that appears. Unplug the cable once: the correct port is the one that disappears. A charge-only cable can light the power LED and still never show a port."},{"type":"text","heading":"Library","body":"Open Tools, Manage Libraries, search for MD_MAX72XX by MajicDesigns, and install version 3.5.1. The finished sketch includes MD_MAX72xx.h and constructs the display as FC16_HW with data on pin 11, clock on pin 13, and chip select on pin 10. Do not install a different MAX7219 library and expect this sketch to compile."},{"type":"expected","heading":"Check","body":"The board menu says Arduino Uno, a serial port is selected, and Library Manager shows MD_MAX72XX 3.5.1 installed."}]$maze13$::jsonb),
  (7, 3, $maze13$Build the game$maze13$, $maze13$Read Joystick Movement$maze13$, $maze13$This excerpt is how the finished sketch turns a stick position into one grid step. Do not upload it on its own.$maze13$, null, $maze13$[{"type":"text","heading":"Centre, deadzone, and direction","body":"Each axis is an analog reading from 0 to 1023. A centred stick rests near 512. Anything within 80 counts of 512 is the centre, so small noise does not move the player. Past that band, the sign of the reading becomes one grid step, either -1 or +1. INVERT_Y starts true, so a rising VRy reading moves toward row 0, the top of the matrix. INVERT_X starts false. If your module faces the other way, you change those two booleans in the finished sketch and upload that whole program again. Leave the pin numbers alone. If both axes leave the deadzone, the sketch keeps the axis farther from 512 and clears the other. If the two distances are equal, it moves neither axis. One push is one horizontal or vertical step, not a diagonal."},{"type":"code","language":"Arduino","filename":"Excerpt from led_matrix_maze.ino","code":"int axisDirection(int raw, bool invert) {\n  int offset = raw - JOY_CENTER;\n  if (abs(offset) <= JOY_DEADZONE) {\n    return 0;\n  }\n  int sign = offset > 0 ? 1 : -1;\n  return invert ? -sign : sign;\n}\n\nvoid stickStep(int xRaw, int yRaw, int &dx, int &dy) {\n  dx = axisDirection(xRaw, INVERT_X);\n  dy = axisDirection(yRaw, INVERT_Y);\n  if (dx != 0 && dy != 0) {\n    int xMag = abs(xRaw - JOY_CENTER);\n    int yMag = abs(yRaw - JOY_CENTER);\n    if (xMag == yMag) {\n      dx = 0;\n      dy = 0;\n    } else if (xMag > yMag) {\n      dy = 0;\n    } else {\n      dx = 0;\n    }\n  }\n}"},{"type":"code_explanation","body":"axisDirection and stickStep belong to the finished sketch. They fill dx and dy, which the movement step uses for one square. This fragment has no setup or loop, so it will not compile on its own."}]$maze13$::jsonb),
  (8, 3, $maze13$Build the game$maze13$, $maze13$Create the Maze and Player$maze13$, $maze13$This excerpt stores one maze and refuses a move onto a wall or off the grid. Do not upload it on its own.$maze13$, null, $maze13$[{"type":"text","heading":"Grid, walls, and coordinates","body":"The display is an 8 by 8 grid. WALLS holds five mazes. Each maze is eight bytes, one per row. Bit 0 of a byte is column 0, the left column, and a set bit is a wall. START_X and START_Y are the open square where the player appears. GOAL_X and GOAL_Y are the open square to reach. beginLevel copies that start into playerX and playerY and prints the level number. wallAt treats a coordinate outside 0 to 7 as a wall. tryStep refuses a move that would leave the grid or land on a wall."},{"type":"code","language":"Arduino","filename":"Excerpt from led_matrix_maze.ino","code":"bool wallAt(int index, int x, int y) {\n  if (x < 0 || y < 0 || x >= GRID || y >= GRID) {\n    return true;\n  }\n  return (WALLS[index][y] & (1 << x)) != 0;\n}\n\n// region: player\nvoid beginLevel(int index) {\n  levelIndex = index;\n  playerX = START_X[index];\n  playerY = START_Y[index];\n  phase = 'p';\n  levelStarted = millis();\n  holdX = 0;\n  holdY = 0;\n  holdSince = levelStarted;\n  lastMove = 0;\n  Serial.print(\"Level \");\n  Serial.println(index + 1);\n}\n\nbool tryStep(int dx, int dy) {\n  if (dx == 0 && dy == 0) {\n    return false;\n  }\n  int nextX = playerX + dx;\n  int nextY = playerY + dy;\n  if (wallAt(levelIndex, nextX, nextY)) {\n    return false;\n  }\n  playerX = nextX;\n  playerY = nextY;\n  return true;\n}\n// end: player"},{"type":"code_explanation","body":"The joystick button calls beginLevel again for the maze you are already on, which puts the player back on the start square. Each maze has a route from its start to its goal. This excerpt is part of the finished sketch, not a program of its own."}]$maze13$::jsonb),
  (9, 3, $maze13$Build the game$maze13$, $maze13$Move and Draw the Player$maze13$, $maze13$These excerpts are the move timing and the three kinds of LED in the finished sketch. Do not upload them on their own.$maze13$, null, $maze13$[{"type":"text","heading":"One square at a time","body":"The first time the stick leaves centre, the player moves one square. Holding the same direction waits 280 ms, then repeats every 180 ms. Releasing the stick clears that hold, so the next push moves immediately. The timing subtracts unsigned millis() values, so a rollover does not freeze the player. loop does not call delay, so the button and the blink stay responsive while you hold the stick."},{"type":"code","language":"Arduino","filename":"Excerpt from led_matrix_maze.ino","code":"bool takeMove(int dx, int dy, unsigned long now) {\n  if (dx == 0 && dy == 0) {\n    holdX = 0;\n    holdY = 0;\n    holdSince = now;\n    return false;\n  }\n  if (dx != holdX || dy != holdY) {\n    holdX = dx;\n    holdY = dy;\n    holdSince = now;\n    lastMove = now;\n    return true;\n  }\n  if (now - holdSince >= MOVE_ARM_MS && now - lastMove >= MOVE_REPEAT_MS) {\n    lastMove = now;\n    return true;\n  }\n  return false;\n}"},{"type":"text","heading":"Walls, player, and goal","body":"drawPlay clears the matrix and visits every square. A wall stays on. The goal is on for 600 ms of each 800 ms. The player is on for 120 ms of each 240 ms, and that fast blink replaces the goal when both occupy the same square. setPoint takes the row first and the column second, matching the FC-16 with its header on the right. update sends that buffer to the chip."},{"type":"code","language":"Arduino","filename":"Excerpt from led_matrix_maze.ino","code":"void drawPlay(unsigned long now) {\n  display.clear();\n  for (int y = 0; y < GRID; y++) {\n    for (int x = 0; x < GRID; x++) {\n      bool on = wallAt(levelIndex, x, y);\n      if (x == GOAL_X[levelIndex] && y == GOAL_Y[levelIndex]) {\n        on = (now % 800) < 600;\n      }\n      if (x == playerX && y == playerY) {\n        on = (now % 240) < 120;\n      }\n      if (on) {\n        display.setPoint(y, x, true);\n      }\n    }\n  }\n  display.update();\n}"}]$maze13$::jsonb),
  (10, 3, $maze13$Build the game$maze13$, $maze13$Add Level Completion and Timing$maze13$, $maze13$These excerpts record the time and accept one button press. They are part of the finished sketch, not programs to upload.$maze13$, null, $maze13$[{"type":"text","heading":"Goal and timer","body":"When a move lands on the goal, completeLevel prints the level number and the milliseconds since that level started. The player is already on the goal square, so the 700 ms success flash is that one square. Levels 1 to 4 then load the next maze. Level 5 prints the total milliseconds since the run started and starts the border chase. The success pause is inside the total and outside the next level’s own timer. The Serial Monitor at 9600 baud is the only clock."},{"type":"code","language":"Arduino","filename":"Excerpt from led_matrix_maze.ino","code":"void completeLevel(unsigned long now) {\n  Serial.print(\"Level \");\n  Serial.print(levelIndex + 1);\n  Serial.print(\" complete in \");\n  Serial.print(now - levelStarted);\n  Serial.println(\" ms\");\n  if (levelIndex >= LEVEL_COUNT - 1) {\n    phase = 'f';\n    Serial.print(\"All five levels in \");\n    Serial.print(now - runStarted);\n    Serial.println(\" ms. Press the joystick button to play again.\");\n  } else {\n    phase = 's';\n    successStarted = now;\n  }\n}"},{"type":"text","heading":"Restart button","body":"SW uses the internal pull-up, so LOW means pressed. readPress accepts a press only after it has stayed down for 40 ms, and holding the button does not repeat it. During a level, that press restarts the level. During the success flash, the next maze is not loaded yet, so the same press restarts the level you just finished. During the final chase, the press returns to level 1 and starts the total time again."},{"type":"code","language":"Arduino","filename":"Excerpt from led_matrix_maze.ino","code":"bool readPress(unsigned long now) {\n  bool rawDown = digitalRead(SW_PIN) == LOW;\n  if (rawDown == buttonDown) {\n    buttonChanged = now;\n    return false;\n  }\n  if (now - buttonChanged < BUTTON_DEBOUNCE_MS) {\n    return false;\n  }\n  buttonDown = rawDown;\n  buttonChanged = now;\n  return rawDown;\n}"},{"type":"tip","body":"Open the Serial Monitor after upload. A centred stick prints nothing. An accepted step prints move, the direction, and the raw analog pair."}]$maze13$::jsonb),
  (11, 3, $maze13$Build the game$maze13$, $maze13$Upload the Complete Game$maze13$, $maze13$This is the only program to paste. The earlier code blocks were excerpts of it.$maze13$, null, $maze13$[{"type":"code","language":"Arduino","filename":"led_matrix_maze.ino","libraries":["MD_MAX72XX 3.5.1"],"code":"#include <MD_MAX72xx.h>\n\nconst int DIN_PIN = 11;\nconst int CLK_PIN = 13;\nconst int CS_PIN = 10;\nconst int X_PIN = A0;\nconst int Y_PIN = A1;\nconst int SW_PIN = 2;\n\nconst int JOY_CENTER = 512;\nconst int JOY_DEADZONE = 80;\nconst bool INVERT_X = false;\nconst bool INVERT_Y = true;\nconst unsigned long MOVE_ARM_MS = 280;\nconst unsigned long MOVE_REPEAT_MS = 180;\nconst unsigned long BUTTON_DEBOUNCE_MS = 40;\nconst unsigned long SUCCESS_MS = 700;\nconst int GRID = 8;\nconst int LEVEL_COUNT = 5;\n\nMD_MAX72XX display(MD_MAX72XX::FC16_HW, DIN_PIN, CLK_PIN, CS_PIN, 1);\n\nconst uint8_t WALLS[LEVEL_COUNT][GRID] = {\n  { 0xff, 0x81, 0xbd, 0x81, 0xbd, 0x81, 0x81, 0xff },\n  { 0xff, 0x81, 0x9f, 0x81, 0xbd, 0x85, 0xa5, 0xff },\n  { 0xff, 0x85, 0xb5, 0xa5, 0xad, 0xa1, 0xaf, 0xff },\n  { 0xff, 0x91, 0xd5, 0x95, 0xb5, 0x85, 0xbd, 0xff },\n  { 0xff, 0x95, 0xd5, 0x91, 0xb7, 0xa1, 0x8d, 0xff }\n};\nconst uint8_t START_X[LEVEL_COUNT] = { 1, 1, 1, 5, 1 };\nconst uint8_t START_Y[LEVEL_COUNT] = { 1, 1, 1, 1, 1 };\nconst uint8_t GOAL_X[LEVEL_COUNT] = { 6, 6, 6, 1, 5 };\nconst uint8_t GOAL_Y[LEVEL_COUNT] = { 6, 6, 6, 6, 6 };\n\nint levelIndex = 0;\nint playerX = 0;\nint playerY = 0;\nchar phase = 'p';\nunsigned long levelStarted = 0;\nunsigned long runStarted = 0;\nunsigned long successStarted = 0;\nint holdX = 0;\nint holdY = 0;\nunsigned long holdSince = 0;\nunsigned long lastMove = 0;\nbool buttonDown = false;\nunsigned long buttonChanged = 0;\n\n// region: direction\nint axisDirection(int raw, bool invert) {\n  int offset = raw - JOY_CENTER;\n  if (abs(offset) <= JOY_DEADZONE) {\n    return 0;\n  }\n  int sign = offset > 0 ? 1 : -1;\n  return invert ? -sign : sign;\n}\n\nvoid stickStep(int xRaw, int yRaw, int &dx, int &dy) {\n  dx = axisDirection(xRaw, INVERT_X);\n  dy = axisDirection(yRaw, INVERT_Y);\n  if (dx != 0 && dy != 0) {\n    int xMag = abs(xRaw - JOY_CENTER);\n    int yMag = abs(yRaw - JOY_CENTER);\n    if (xMag == yMag) {\n      dx = 0;\n      dy = 0;\n    } else if (xMag > yMag) {\n      dy = 0;\n    } else {\n      dx = 0;\n    }\n  }\n}\n// end: direction\n\nbool wallAt(int index, int x, int y) {\n  if (x < 0 || y < 0 || x >= GRID || y >= GRID) {\n    return true;\n  }\n  return (WALLS[index][y] & (1 << x)) != 0;\n}\n\n// region: player\nvoid beginLevel(int index) {\n  levelIndex = index;\n  playerX = START_X[index];\n  playerY = START_Y[index];\n  phase = 'p';\n  levelStarted = millis();\n  holdX = 0;\n  holdY = 0;\n  holdSince = levelStarted;\n  lastMove = 0;\n  Serial.print(\"Level \");\n  Serial.println(index + 1);\n}\n\nbool tryStep(int dx, int dy) {\n  if (dx == 0 && dy == 0) {\n    return false;\n  }\n  int nextX = playerX + dx;\n  int nextY = playerY + dy;\n  if (wallAt(levelIndex, nextX, nextY)) {\n    return false;\n  }\n  playerX = nextX;\n  playerY = nextY;\n  return true;\n}\n// end: player\n\nbool takeMove(int dx, int dy, unsigned long now) {\n  if (dx == 0 && dy == 0) {\n    holdX = 0;\n    holdY = 0;\n    holdSince = now;\n    return false;\n  }\n  if (dx != holdX || dy != holdY) {\n    holdX = dx;\n    holdY = dy;\n    holdSince = now;\n    lastMove = now;\n    return true;\n  }\n  if (now - holdSince >= MOVE_ARM_MS && now - lastMove >= MOVE_REPEAT_MS) {\n    lastMove = now;\n    return true;\n  }\n  return false;\n}\n\nbool readPress(unsigned long now) {\n  bool rawDown = digitalRead(SW_PIN) == LOW;\n  if (rawDown == buttonDown) {\n    buttonChanged = now;\n    return false;\n  }\n  if (now - buttonChanged < BUTTON_DEBOUNCE_MS) {\n    return false;\n  }\n  buttonDown = rawDown;\n  buttonChanged = now;\n  return rawDown;\n}\n\n// region: draw\nvoid drawPlay(unsigned long now) {\n  display.clear();\n  for (int y = 0; y < GRID; y++) {\n    for (int x = 0; x < GRID; x++) {\n      bool on = wallAt(levelIndex, x, y);\n      if (x == GOAL_X[levelIndex] && y == GOAL_Y[levelIndex]) {\n        on = (now % 800) < 600;\n      }\n      if (x == playerX && y == playerY) {\n        on = (now % 240) < 120;\n      }\n      if (on) {\n        display.setPoint(y, x, true);\n      }\n    }\n  }\n  display.update();\n}\n// end: draw\n\nvoid drawSuccess(unsigned long now) {\n  display.clear();\n  bool flash = (now / 100) % 2 == 0;\n  if (flash) {\n    display.setPoint(playerY, playerX, true);\n    display.setPoint(GOAL_Y[levelIndex], GOAL_X[levelIndex], true);\n  }\n  display.update();\n}\n\nvoid drawFinished(unsigned long now) {\n  display.clear();\n  int step = (int)((now / 80) % 28);\n  int cursor = 0;\n  for (int x = 0; x < GRID; x++) {\n    if (cursor == step) {\n      display.setPoint(0, x, true);\n    }\n    cursor++;\n  }\n  for (int y = 1; y < GRID; y++) {\n    if (cursor == step) {\n      display.setPoint(y, GRID - 1, true);\n    }\n    cursor++;\n  }\n  for (int x = GRID - 2; x >= 0; x--) {\n    if (cursor == step) {\n      display.setPoint(GRID - 1, x, true);\n    }\n    cursor++;\n  }\n  for (int y = GRID - 2; y >= 1; y--) {\n    if (cursor == step) {\n      display.setPoint(y, 0, true);\n    }\n    cursor++;\n  }\n  display.update();\n}\n\nvoid completeLevel(unsigned long now) {\n  Serial.print(\"Level \");\n  Serial.print(levelIndex + 1);\n  Serial.print(\" complete in \");\n  Serial.print(now - levelStarted);\n  Serial.println(\" ms\");\n  if (levelIndex >= LEVEL_COUNT - 1) {\n    phase = 'f';\n    Serial.print(\"All five levels in \");\n    Serial.print(now - runStarted);\n    Serial.println(\" ms. Press the joystick button to play again.\");\n  } else {\n    phase = 's';\n    successStarted = now;\n  }\n}\n\nvoid setup() {\n  pinMode(SW_PIN, INPUT_PULLUP);\n  Serial.begin(9600);\n  display.begin();\n  display.control(MD_MAX72XX::INTENSITY, 2);\n  display.clear();\n  // region: one-led\n  display.setPoint(0, 0, true);\n  display.update();\n  delay(300);\n  display.clear();\n  display.update();\n  // end: one-led\n  runStarted = millis();\n  buttonChanged = runStarted;\n  beginLevel(0);\n}\n\nvoid loop() {\n  unsigned long now = millis();\n  if (readPress(now)) {\n    if (phase == 'f') {\n      runStarted = now;\n      beginLevel(0);\n      Serial.println(\"Back to level 1.\");\n    } else {\n      beginLevel(levelIndex);\n      Serial.println(\"Level restarted.\");\n    }\n    return;\n  }\n\n  if (phase == 's') {\n    drawSuccess(now);\n    if (now - successStarted >= SUCCESS_MS) {\n      beginLevel(levelIndex + 1);\n    }\n    return;\n  }\n\n  if (phase == 'f') {\n    drawFinished(now);\n    return;\n  }\n\n  int xRaw = analogRead(X_PIN);\n  int yRaw = analogRead(Y_PIN);\n  int dx = 0;\n  int dy = 0;\n  stickStep(xRaw, yRaw, dx, dy);\n  if (takeMove(dx, dy, now) && tryStep(dx, dy)) {\n    Serial.print(\"move \");\n    Serial.print(dx);\n    Serial.print(\",\");\n    Serial.print(dy);\n    Serial.print(\" raw \");\n    Serial.print(xRaw);\n    Serial.print(\",\");\n    Serial.println(yRaw);\n    if (playerX == GOAL_X[levelIndex] && playerY == GOAL_Y[levelIndex]) {\n      completeLevel(now);\n    }\n  }\n  if (phase == 'p') {\n    drawPlay(now);\n  }\n}\n"},{"type":"text","heading":"Upload","body":"Create a sketch named led_matrix_maze and replace its contents with the program above. Do not paste an earlier excerpt underneath it. Board is Arduino Uno. Port is the Uno port. Click Upload. When the IDE finishes, open the Serial Monitor and set it to 9600 baud. Inside setup, intensity is set to 2, then setPoint(0, 0, true) and update() light row 0, column 0. That is the top-left LED when the FC-16 input header is on the right. After a short pause the same LED turns off and level 1 is drawn. That corner flash is the matrix check inside this sketch. If it never lights, the usual causes are intensity left at 0, CLK and DIN swapped, or the input header on the left. The last step lists those checks."},{"type":"expected","heading":"What you should observe","body":"One LED flashes in the top-left corner, then the first maze appears. Walls stay lit. One dot blinks quickly on the start square. Another square blinks slowly. That slow square is the goal."}]$maze13$::jsonb),
  (12, 4, $maze13$Test and troubleshoot$maze13$, $maze13$Play and Test All Five Levels$maze13$, $maze13$Finish each maze, then use the button and the two invert lines if a control feels backwards.$maze13$, null, $maze13$[{"type":"test","heading":"Play","body":"Move to the slow square on each maze. The monitor prints a time in milliseconds when a level completes. After level 5, one LED runs around the border and the monitor prints the total. Press the stick button to return to level 1. During an earlier level, the same button puts you back on that level’s start square. If a wire looks doubtful, go back to Check the Complete Circuit and use that diagram."},{"type":"troubleshooting","heading":"If something is wrong","items":[{"problem":"The matrix stays dark","solution":"Confirm MD_MAX72XX 3.5.1, FC16_HW, DIN on D11, CLK on D13, and CS on D10. The female socket is on the matrix pin and the male pin is in the Uno. VCC must come from the red rail and GND from the blue rail. Intensity stays at 2. Compare the wires with the completed diagram on Check the Complete Circuit. A charge-only USB cable can power the Uno LED and still fail to upload."},{"problem":"The maze is rotated or mirrored","solution":"Turn the module so the LED face is up and the input header is on the right, top to bottom CLK, CS, DIN, GND, VCC. Row 0 is then the top. If the silk order differs, move the jumpers to match the silk. Do not push the header into the breadboard."},{"problem":"The stick moves the wrong way","solution":"Change INVERT_X or INVERT_Y in the finished sketch and upload that whole program again. Leave the pin numbers alone. A centred stick should print nothing and should not move the player."},{"problem":"The player jitters or runs away","solution":"Leave the deadzone at 80 and the repeat at 280 ms then 180 ms. A noisy module that never rests near 512 needs a larger JOY_DEADZONE, not a deleted check. Do not add delay() inside loop."},{"problem":"The button restarts more than once","solution":"SW must go to D2 and the pin mode must stay INPUT_PULLUP. The press is accepted only after 40 ms and only on the change to pressed. Holding the button should produce one restart."}]},{"type":"expected","heading":"Finished","body":"You can complete all five mazes, read each level time and the final total in the Serial Monitor, and start a new run with the joystick button."}]$maze13$::jsonb)
) as step(sort_order, stage_sort_order, stage_title, title, description, tip, blocks)
where project.slug = '25';
